-- =============================================================
-- CAH Cinema background seed data
-- -------------------------------------------------------------
-- Run this after cah_cinema.sql when you need demo/test data.
-- This script is idempotent and intentionally avoids transactional
-- tables generated by user activity: bookings, tickets, food_orders,
-- payment_confirmations, invoices, pending_ticket_items,
-- booking_food_draft_items, food_order_items, and outbox_events.
-- =============================================================

BEGIN;

-- =============================================================
-- 1. Lookup data
-- =============================================================

INSERT INTO roles (role_name) VALUES ('ROLE_USER'), ('ROLE_ADMIN')
ON CONFLICT (role_name) DO NOTHING;

INSERT INTO genres (name, created_at, is_deleted)
SELECT v.name, CURRENT_TIMESTAMP, FALSE
FROM (VALUES
    ('Action'),
    ('Adventure'),
    ('Animation'),
    ('Comedy'),
    ('Crime'),
    ('Drama'),
    ('Family'),
    ('Fantasy'),
    ('Horror'),
    ('Musical'),
    ('Mystery'),
    ('Romance'),
    ('Science Fiction'),
    ('Thriller'),
    ('War'),
    ('Documentary')
) AS v(name)
WHERE NOT EXISTS (
    SELECT 1 FROM genres g WHERE LOWER(g.name) = LOWER(v.name) AND g.is_deleted = FALSE
);

INSERT INTO seat_types (type_name, price_multiplier)
SELECT v.type_name, v.price_multiplier
FROM (VALUES
    ('NORMAL', 1.00),
    ('VIP', 1.25),
    ('COUPLE', 1.80),
    ('AISLE', 0.00)
) AS v(type_name, price_multiplier)
WHERE NOT EXISTS (
    SELECT 1 FROM seat_types st WHERE st.type_name = v.type_name
);

INSERT INTO price_configs (day_type, time_slot, movie_format, multiplier)
SELECT v.day_type, v.time_slot, v.movie_format, v.multiplier
FROM (VALUES
    ('WEEKDAY', NULL, NULL, 1.00),
    ('WEEKEND', NULL, NULL, 1.20),
    ('HOLIDAY', NULL, NULL, 1.50),
    (NULL, 'MORNING', NULL, 0.90),
    (NULL, 'AFTERNOON', NULL, 1.00),
    (NULL, 'EVENING', NULL, 1.15),
    (NULL, NULL, '2D', 1.00),
    (NULL, NULL, '3D', 1.20),
    (NULL, NULL, 'IMAX', 1.45)
) AS v(day_type, time_slot, movie_format, multiplier)
WHERE NOT EXISTS (
    SELECT 1
    FROM price_configs pc
    WHERE pc.day_type IS NOT DISTINCT FROM v.day_type
      AND pc.time_slot IS NOT DISTINCT FROM v.time_slot
      AND pc.movie_format IS NOT DISTINCT FROM v.movie_format
);

INSERT INTO holidays (name, holiday_date, is_recurring)
SELECT v.name, v.holiday_date, v.is_recurring
FROM (VALUES
    ('Tết Dương lịch', DATE '2026-01-01', TRUE),
    ('Valentine', DATE '2026-02-14', TRUE),
    ('Giỗ Tổ Hùng Vương 2026', DATE '2026-04-18', FALSE),
    ('Ngày Giải phóng miền Nam', DATE '2026-04-30', TRUE),
    ('Ngày Quốc tế Lao động', DATE '2026-05-01', TRUE),
    ('Quốc khánh Việt Nam', DATE '2026-09-02', TRUE),
    ('Giáng sinh', DATE '2026-12-25', TRUE)
) AS v(name, holiday_date, is_recurring)
WHERE NOT EXISTS (
    SELECT 1 FROM holidays h WHERE h.name = v.name AND h.holiday_date = v.holiday_date
);

-- =============================================================
-- 2. Cinemas, rooms, and seats
-- =============================================================

INSERT INTO cinemas (name, address, image_url, hotline, created_at, is_deleted)
SELECT v.name, v.address, v.image_url, v.hotline, CURRENT_TIMESTAMP, FALSE
FROM (VALUES
    ('CAH Cinema Landmark 81', 'Tầng B1, Vincom Center Landmark 81, 720A Điện Biên Phủ, Bình Thạnh, TP.HCM', 'https://cdn.cah.local/cinemas/landmark81.jpg', '028 7300 8181'),
    ('CAH Cinema Sư Vạn Hạnh', 'Tầng 6, Vạn Hạnh Mall, 11 Sư Vạn Hạnh, Quận 10, TP.HCM', 'https://cdn.cah.local/cinemas/su-van-hanh.jpg', '028 7300 1010'),
    ('CAH Cinema Crescent Mall', 'Tầng 5, Crescent Mall, 101 Tôn Dật Tiên, Quận 7, TP.HCM', 'https://cdn.cah.local/cinemas/crescent-mall.jpg', '028 7300 0707'),
    ('CAH Cinema Vincom Bà Triệu', 'Tầng 6, Vincom Center, 191 Bà Triệu, Hai Bà Trưng, Hà Nội', 'https://cdn.cah.local/cinemas/vincom-ba-trieu.jpg', '024 7300 1919'),
    ('CAH Cinema Royal City', 'Tầng B2, Royal City, 72A Nguyễn Trãi, Thanh Xuân, Hà Nội', 'https://cdn.cah.local/cinemas/royal-city.jpg', '024 7300 7272'),
    ('CAH Cinema Đà Nẵng Riverside', 'Tầng 4, Indochina Riverside Mall, 74 Bạch Đằng, Hải Châu, Đà Nẵng', 'https://cdn.cah.local/cinemas/da-nang-riverside.jpg', '0236 7300 7474')
) AS v(name, address, image_url, hotline)
WHERE NOT EXISTS (
    SELECT 1 FROM cinemas c WHERE c.name = v.name AND c.is_deleted = FALSE
);

INSERT INTO rooms (cinema_id, room_name, is_deleted)
SELECT c.cinema_id, v.room_name, FALSE
FROM cinemas c
CROSS JOIN (VALUES
    ('Phòng 01 - Standard'),
    ('Phòng 02 - Premium'),
    ('Phòng 03 - IMAX')
) AS v(room_name)
WHERE c.name IN (
    'CAH Cinema Landmark 81',
    'CAH Cinema Sư Vạn Hạnh',
    'CAH Cinema Crescent Mall',
    'CAH Cinema Vincom Bà Triệu',
    'CAH Cinema Royal City',
    'CAH Cinema Đà Nẵng Riverside'
)
AND NOT EXISTS (
    SELECT 1 FROM rooms r
    WHERE r.cinema_id = c.cinema_id
      AND r.room_name = v.room_name
      AND r.is_deleted = FALSE
);

DO $$
DECLARE
    row_column_name TEXT;
    col_column_name TEXT;
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'seats'
          AND column_name = 'seat_row'
    ) AND EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'seats'
          AND column_name = 'seat_col'
    ) THEN
        row_column_name := 'seat_row';
        col_column_name := 'seat_col';
    ELSIF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'seats'
          AND column_name = 'row'
    ) AND EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'seats'
          AND column_name = 'col'
    ) THEN
        row_column_name := 'row';
        col_column_name := 'col';
    ELSE
        RAISE EXCEPTION 'Cannot seed seats: table %.seats must have either (seat_row, seat_col) from cah_cinema.sql or legacy (row, col) columns', current_schema();
    END IF;

    EXECUTE format($seed$
        WITH seat_type_ids AS (
            SELECT
                MAX(CASE WHEN type_name = 'NORMAL' THEN seat_type_id END) AS normal_id,
                MAX(CASE WHEN type_name = 'VIP' THEN seat_type_id END) AS vip_id,
                MAX(CASE WHEN type_name = 'COUPLE' THEN seat_type_id END) AS couple_id,
                MAX(CASE WHEN type_name = 'AISLE' THEN seat_type_id END) AS aisle_id
            FROM seat_types
        ), target_rooms AS (
            SELECT r.room_id, r.room_name
            FROM rooms r
            JOIN cinemas c ON c.cinema_id = r.cinema_id
            WHERE c.name LIKE 'CAH Cinema%%'
              AND r.is_deleted = FALSE
        ), physical_seats AS (
            SELECT
                tr.room_id,
                row_no::NUMERIC(5,1) AS generated_seat_row,
                col_no::NUMERIC(5,1) AS generated_seat_col,
                CASE
                    WHEN row_no = 8 THEN sti.couple_id
                    WHEN row_no BETWEEN 4 AND 7 THEN sti.vip_id
                    ELSE sti.normal_id
                END AS seat_type_id,
                CASE WHEN row_no = 1 AND col_no IN (1, 12) THEN 'PREPARE' ELSE 'ACTIVE' END AS status
            FROM target_rooms tr
            CROSS JOIN seat_type_ids sti
            CROSS JOIN generate_series(1, 8) AS row_no
            CROSS JOIN generate_series(1, 12) AS col_no
        ), vertical_aisles AS (
            SELECT
                tr.room_id,
                row_no::NUMERIC(5,1) AS generated_seat_row,
                6.5::NUMERIC(5,1) AS generated_seat_col,
                sti.aisle_id AS seat_type_id,
                'ACTIVE' AS status
            FROM target_rooms tr
            CROSS JOIN seat_type_ids sti
            CROSS JOIN generate_series(1, 8) AS row_no
        ), horizontal_aisles AS (
            SELECT
                tr.room_id,
                4.5::NUMERIC(5,1) AS generated_seat_row,
                col_no::NUMERIC(5,1) AS generated_seat_col,
                sti.aisle_id AS seat_type_id,
                'ACTIVE' AS status
            FROM target_rooms tr
            CROSS JOIN seat_type_ids sti
            CROSS JOIN generate_series(1, 12) AS col_no
        ), all_seats AS (
            SELECT * FROM physical_seats
            UNION ALL
            SELECT * FROM vertical_aisles
            UNION ALL
            SELECT * FROM horizontal_aisles
        )
        INSERT INTO seats (room_id, %I, %I, seat_type_id, status, is_deleted)
        SELECT s.room_id, s.generated_seat_row, s.generated_seat_col, s.seat_type_id, s.status, FALSE
        FROM all_seats s
        WHERE NOT EXISTS (
            SELECT 1 FROM seats existing
            WHERE existing.room_id = s.room_id
              AND existing.%I = s.generated_seat_row
              AND existing.%I = s.generated_seat_col
              AND existing.is_deleted = FALSE
        )
    $seed$, row_column_name, col_column_name, row_column_name, col_column_name);
END $$;

