        ('Frozen 3', 'Elsa, Anna và những người bạn bước vào hành trình mới để hiểu sâu hơn về phép thuật của Arendelle.', 105, DATE '2026-11-25', 'Jennifer Lee', 'Idina Menzel, Kristen Bell, Josh Gad', 'P', 'https://image.tmdb.org/t/p/w500/sample-frozen-3.jpg', 'https://www.youtube.com/watch?v=sample-frozen3'),
        ('The Hunger Games: Sunrise on the Reaping', 'Câu chuyện tiền truyện về kỳ Hunger Games thứ 50 mở ra góc nhìn mới về Panem.', 135, DATE '2026-11-20', 'Francis Lawrence', 'TBA', 'T16', 'https://image.tmdb.org/t/p/w500/sample-sunrise-reaping.jpg', 'https://www.youtube.com/watch?v=sample-hunger-games')
    ) AS m(title, description, duration, release_date, director_name, actor_list, age_rating, poster_url, trailer_url)
)
INSERT INTO movies (title, description, duration, release_date, director_name, actor_list, age_rating, poster_url, trailer_url, created_at, updated_at, is_deleted)
SELECT ms.title, ms.description, ms.duration, ms.release_date, ms.director_name, ms.actor_list, ms.age_rating, ms.poster_url, ms.trailer_url, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, FALSE
FROM movie_seed ms
WHERE NOT EXISTS (
    SELECT 1 FROM movies m
    WHERE LOWER(m.title) = LOWER(ms.title)
      AND m.release_date = ms.release_date
      AND m.is_deleted = FALSE
);

WITH links(title, genre_name) AS (
    VALUES
        ('Michael', 'Drama'), ('Michael', 'Musical'),
