INSERT INTO movie_genres (movie_id, genre_id)
SELECT m.movie_id, g.genre_id
FROM links l
JOIN movies m ON LOWER(m.title) = LOWER(l.title) AND m.is_deleted = FALSE
JOIN genres g ON LOWER(g.name) = LOWER(l.genre_name) AND g.is_deleted = FALSE
ON CONFLICT (movie_id, genre_id) DO NOTHING;

