-- =============================================================
-- 6. Showtimes from 2026-05-09 to 2026-06-07
-- =============================================================

WITH target_rooms AS (
    SELECT r.room_id, r.room_name, c.cinema_id
    FROM rooms r
    JOIN cinemas c ON c.cinema_id = r.cinema_id
    WHERE c.name LIKE 'CAH Cinema%'
      AND r.is_deleted = FALSE
), slots AS (
    SELECT * FROM (VALUES
        (1, TIME '08:15:00', 0),
        (2, TIME '12:00:00', 1),
        (3, TIME '15:45:00', 2),
        (4, TIME '19:30:00', 3)
    ) AS s(slot_no, start_clock, movie_offset)
), movie_pool AS (
    SELECT
        m.movie_id,
        m.duration,
        ROW_NUMBER() OVER (ORDER BY m.release_date DESC, m.movie_id) AS rn,
        COUNT(*) OVER () AS total_movies
    FROM movies m
    WHERE m.title IN (
        'Michael',
        'Mortal Kombat II',
        'The Mandalorian and Grogu',
        'The Sheep Detectives',
        'Yêu Nữ Thích Hàng Hiệu 2',
        'Doraemon: Nobita Và Cuộc Phiêu Lưu Ở Thế Giới Tranh',
        'Thám Tử Kiên: Kỳ Án Không Đầu',
        'Lật Mặt 9: Vòng Xoáy Gia Đình',
        'Supergirl: Woman of Tomorrow',
        'Toy Story 5',
        'Moana: Live Action',
        'Scream 7',
        'Project Hail Mary',
        'Minions & Monsters',
        'Thẩm Mỹ Viện Âm Phủ',
        'Trạng Quỳnh Nhí: Truyền Thuyết Hồ Sen',
        'Ballerina',
        'Mission: Impossible - The Final Reckoning',
        'How to Train Your Dragon',
        'Elio',
        'F1 The Movie',
        'Jurassic World Rebirth',
        'The Fantastic Four: First Steps',
        'Wicked: For Good',
        'Avatar: Fire and Ash'
    )
    AND m.is_deleted = FALSE
), schedule_seed AS (
    SELECT
        tr.room_id,
        mp.movie_id,
        CASE
            WHEN tr.room_name LIKE '%IMAX%' THEN 'IMAX'
            WHEN MOD((EXTRACT(DOY FROM d.day_date)::INT + s.slot_no + tr.room_id)::INT, 5) = 0 THEN '3D'
            ELSE '2D'
        END AS format,
        (d.day_date::DATE + s.start_clock) AS start_time,
        (d.day_date::DATE + s.start_clock + (mp.duration || ' minutes')::INTERVAL) AS end_time,
        CASE
            WHEN tr.room_name LIKE '%IMAX%' THEN 145000.00
            WHEN MOD((EXTRACT(DOY FROM d.day_date)::INT + s.slot_no + tr.room_id)::INT, 5) = 0 THEN 115000.00
            WHEN s.slot_no = 1 THEN 75000.00
            WHEN s.slot_no >= 4 THEN 105000.00
            ELSE 90000.00
        END AS base_price
    FROM target_rooms tr
    CROSS JOIN generate_series(DATE '2026-05-09', DATE '2026-06-07', INTERVAL '1 day') AS d(day_date)
    CROSS JOIN slots s
    JOIN movie_pool mp
      ON mp.rn = MOD((EXTRACT(DOY FROM d.day_date)::INT + tr.room_id::INT + s.movie_offset), mp.total_movies) + 1
)
INSERT INTO showtimes (room_id, movie_id, format, start_time, end_time, base_price, is_deleted, status)
SELECT ss.room_id, ss.movie_id, ss.format, ss.start_time, ss.end_time, ss.base_price, FALSE, 'AVAILABLE'
FROM schedule_seed ss
WHERE NOT EXISTS (
    SELECT 1 FROM showtimes st
    WHERE st.room_id = ss.room_id
      AND st.start_time = ss.start_time
      AND st.is_deleted = FALSE
);

COMMIT;
